import{apiClient}from"./client";const adminLogin=async a=>{return(await apiClient.post("/auth/login",a)).data},getAdminCars=async a=>{return(await apiClient.get("/admin/cars",{params:{organizationSlug:a}})).data},createAdminCar=async(a,i)=>{return(await apiClient.post("/admin/cars",a,{params:{organizationSlug:i}})).data},updateAdminCar=async(a,i,t)=>{return(await apiClient.put("/admin/cars/"+a,t,{params:{organizationSlug:i}})).data},deleteAdminCar=async(a,i)=>{return(await apiClient.delete("/admin/cars/"+a,{params:{organizationSlug:i}})).data},getAdminMe=async()=>{return(await apiClient.get("/admin/me")).data};export{adminLogin,getAdminCars,createAdminCar,updateAdminCar,deleteAdminCar,getAdminMe};